import { IdGenerator } from "../domain/id-generator";
import { Project } from "../domain/project";
import { ProjectRepository } from "../domain/project-repository";
import { ApplicationError } from "./application-error";
import { CreateProjectInput, ProjectOutput } from "./dtos";

export class CreateProjectUseCase {
  public constructor(private readonly projects: ProjectRepository, private readonly ids: IdGenerator) {}

  public async execute(input: CreateProjectInput): Promise<ProjectOutput> {
    if (!input.name?.trim()) throw new ApplicationError("name is required", 400);
    const project = new Project(this.ids.next(), input.name.trim());
    await this.projects.save(project);
    return { id: project.id, name: project.name };
  }
}

