import { ProjectRepository } from "../domain/project-repository";
import { Task } from "../domain/task";
import { TaskRepository } from "../domain/task-repository";
import { ApplicationError } from "./application-error";
import { ListTasksInput, TaskOutput } from "./dtos";

export class ListProjectTasksUseCase {
  public constructor(private readonly tasks: TaskRepository, private readonly projects: ProjectRepository) {}

  public async execute(input: ListTasksInput): Promise<TaskOutput[]> {
    if (!(await this.projects.findById(input.projectId))) throw new ApplicationError("project not found", 404);
    const tasks = await this.tasks.findByProjectId(input.projectId, { status: input.status, assigneeId: input.assigneeId });
    return tasks.map((task) => this.toOutput(task));
  }

  private toOutput(task: Task): TaskOutput {
    return { id: task.id, projectId: task.projectId, title: task.title, description: task.description, dueDate: task.dueDate?.toISOString(), assigneeId: task.assigneeId, status: task.getStatus() };
  }
}

